head.script:
scwin.screenId = "jldfil02000";

///////// 1. 변수 및 선언 영역 /////////



///////// 2. 초기화 영역 /////////

/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        $(".pop_bg").css("overflow", "hidden");
        const kind = '<iframe src="' + scwin.urlInfo() + '/common/krxPapago.do?method=openPapagoTranslator" width="1423" height=824" scrolling="no"></iframe>';
        (($c.util.getComponent('txt_content')) && ($c.util.getComponent('txt_content')).setValue ? ($c.util.getComponent('txt_content')).setValue(kind) : (($c.util.getComponent('txt_content')) && ($c.util.getComponent('txt_content')).setText ? ($c.util.getComponent('txt_content')).setText(kind) : void (kind)));
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil02000.onpageload' }); }
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { console.warn("[sdd] 전환 파라미터 수신 대상 없음: dma_pageContext — 읽는 자리 0"); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
        scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil02000.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////



///////// 4. 서브미션 콜백 영역 /////////



///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.urlInfo
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.urlInfo = function () {
    /* sdd-asis-lifecycle:begin fn_urlInfo — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let returnUrl = '';
    const url = location.host;
    if (url === ('localhost:8081') || url === ('idev-filing.krx.co.kr')) {
        returnUrl = 'https://idev-kind.krx.co.kr';
    } else {
        if (url === ('dev-filing.krx.co.kr')) {
            returnUrl = 'https://dev-kind.krx.co.kr';
        } else {
            if (url === ('test-filing.krx.co.kr')) {
                returnUrl = 'https://test-kind.krx.co.kr';
            } else {
                if (url === ('filing.krx.co.kr')) {
                    returnUrl = 'https://kind.krx.co.kr';
                } else {
                    if (url === ('dr-filing.krx.co.kr')) {
                        returnUrl = 'https://dr-kind.krx.co.kr';
                    }
                }
            }
        }
    }
    return returnUrl;
    /* sdd-asis-lifecycle:end */
};
